import{_ as a,a as o,o as t,ay as r}from"./chunks/framework.B6Es4Ycg.js";const f=JSON.parse('{"title":"Tools","description":"","frontmatter":{},"headers":[],"relativePath":"tools/index.md","filePath":"tools/index.md"}'),s={name:"tools/index.md"};function n(i,e,l,d,c,p){return t(),o("div",null,e[0]||(e[0]=[r('<h1 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to “Tools”">​</a></h1><p>Small web tools made while building Openpod. They all run in the browser, with nothing to install.</p><div class="op-cards"><a class="op-card" href="./sync"><strong>OpenPod Sync</strong><span>Fill the SD card from your music folders, right in the browser: see what&#39;s new, convert what the player can&#39;t play, remove albums.</span></a><a class="op-card" href="./clickwheel"><strong>Click wheel designer</strong><span>Generate a capacitive click wheel footprint (pads and edge cuts) as PNG for KiCad, and simulate how the finger position is interpolated.</span></a><a class="op-card" href="./pinout"><strong>Pinout</strong><span>See which STM32F446 pin drives what on the final board (LQFP100) and on the Nucleo prototype (LQFP64).</span></a><a class="op-card" href="./ui-builder"><strong>UI builder</strong><span>Preview every firmware screen, tweak the colour palette and export the sprites and theme headers.</span></a><a class="op-card" href="https://leo-nicolle.github.io/open-pod/userscripts/radiofrance-podcasts.user.js"><strong>Radio France podcast downloader</strong><span>A Tampermonkey userscript: on any Radio France podcast page, tick the episodes and download them into <code>~/Podcasts</code>, ready to sync.</span></a></div><p>The Radio France downloader is a <a href="https://leo-nicolle.github.io/open-pod/userscripts/radiofrance-podcasts.user.js" target="_blank" rel="noreferrer">userscript</a>: install <a href="https://www.tampermonkey.net/" target="_blank" rel="noreferrer">Tampermonkey</a>, open the link and confirm. It needs Chrome or Edge (the File System Access API); Firefox/Safari fall back to a normal download. Once the episodes are in <code>~/Podcasts</code>, add that folder as a library in <a href="./sync.html">OpenPod Sync</a> and it syncs to the card.</p><p>Full pin tables: <a href="./pinout-table-lqfp100.html">LQFP100 (final board)</a> · <a href="./pinout-table.html">LQFP64 (Nucleo-F446RE)</a>.</p>',5)]))}const m=a(s,[["render",n]]);export{f as __pageData,m as default};
